import { randomUUID } from 'node:crypto';

const UUID = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';
const KEY_PATTERN = new RegExp(`^(${UUID})/(${UUID})$`);
const UUID_PATTERN = new RegExp(`^${UUID}$`);

/**
 * Object keys are `<organisation uuid>/<object uuid>`, generated by the server.
 * Nothing supplied by a user (file name, MIME type, path) is ever part of a key.
 */
export function newObjectKey(orgId: string): string {
  if (!UUID_PATTERN.test(orgId)) {
    throw new StorageError('invalid_key', 'organisation id is not a lower-case UUID');
  }
  return `${orgId}/${randomUUID()}`;
}

export function isValidObjectKey(key: unknown): key is string {
  return typeof key === 'string' && key.length === 73 && KEY_PATTERN.test(key);
}

/** Splits a key into its two UUID segments, or throws `invalid_key`. */
export function parseObjectKey(key: unknown): { orgId: string; objectId: string } {
  if (!isValidObjectKey(key)) {
    throw new StorageError('invalid_key', 'object key is not of the form <uuid>/<uuid>');
  }
  const match = KEY_PATTERN.exec(key);
  if (match === null || match[1] === undefined || match[2] === undefined) {
    throw new StorageError('invalid_key', 'object key is not of the form <uuid>/<uuid>');
  }
  return { orgId: match[1], objectId: match[2] };
}

/** True when the key belongs to the organisation. Use before every read on behalf of a tenant. */
export function keyBelongsToOrg(key: string, orgId: string): boolean {
  return isValidObjectKey(key) && key.startsWith(`${orgId}/`) && UUID_PATTERN.test(orgId);
}

export type StorageErrorCode =
  | 'invalid_key'
  | 'not_found'
  | 'already_exists'
  | 'too_large'
  | 'invalid_range'
  | 'not_a_regular_file'
  | 'io_error';

export class StorageError extends Error {
  readonly code: StorageErrorCode;
  constructor(code: StorageErrorCode, message: string, options?: { cause?: unknown }) {
    super(message, options);
    this.name = 'StorageError';
    this.code = code;
  }
}
